const now = new Date();
const weekStart = new Date(now);
weekStart.setDate(weekStart.getDate() - 7);

const repoFull = ($env.GITHUB_REPO || '').trim();
if (!repoFull.includes('/')) {
  throw new Error('Set GITHUB_REPO to owner/repo format.');
}
const [owner, name] = repoFull.split('/');

const githubToken = ($env.GITHUB_TOKEN || '').trim();
const anthropicApiKey = ($env.ANTHROPIC_API_KEY || '').trim();
const discordWebhookUrl = ($env.DISCORD_WEBHOOK_URL || '').trim();

if (!githubToken) throw new Error('Set GITHUB_TOKEN with repo read access.');
if (!anthropicApiKey) throw new Error('Set ANTHROPIC_API_KEY.');
if (!discordWebhookUrl) throw new Error('Set DISCORD_WEBHOOK_URL.');

return [{
  json: {
    owner,
    repo: name,
    repoFullName: `${owner}/${name}`,
    language: ($env.SUMMARY_LANGUAGE || 'EN').trim().toUpperCase() === 'FR' ? 'FR' : 'EN',
    weekStart: weekStart.toISOString(),
    weekEnd: now.toISOString(),
    githubToken,
    anthropicApiKey,
    discordWebhookUrl
  }
}];

const config = $('Load Configuration').first().json;
const weekStart = new Date(config.weekStart);
const weekEnd = new Date(config.weekEnd);

const inWindow = (value) => {
  if (!value) return false;
  const date = new Date(value);
  return date >= weekStart && date <= weekEnd;
};

const collectRecords = (nodeName) => {
  try {
    const items = $(nodeName).all();
    if (!items.length) return [];
    const first = items[0].json;
    if (Array.isArray(first)) return first;
    return items.map((item) => item.json).filter((row) => row && typeof row === 'object');
  } catch (_) {
    return [];
  }
};

const commits = collectRecords('Fetch Commits')
  .filter((commit) => inWindow(commit.commit?.author?.date || commit.commit?.committer?.date))
  .map((commit) => ({
    sha: (commit.sha || '').slice(0, 7),
    message: commit.commit?.message?.split('\n')[0] || '',
    author: commit.author?.login || commit.commit?.author?.name || 'unknown',
    date: commit.commit?.author?.date || commit.commit?.committer?.date,
    url: commit.html_url
  }));

const closedIssues = collectRecords('Fetch Closed Issues')
  .filter((issue) => !issue.pull_request && inWindow(issue.closed_at))
  .map((issue) => ({
    number: issue.number,
    title: issue.title,
    closedAt: issue.closed_at,
    url: issue.html_url
  }));

const mergedPullRequests = collectRecords('Fetch Closed Pull Requests')
  .filter((pr) => pr.merged_at && inWindow(pr.merged_at))
  .map((pr) => ({
    number: pr.number,
    title: pr.title,
    author: pr.user?.login || 'unknown',
    mergedAt: pr.merged_at,
    url: pr.html_url
  }));

const instruction = config.language === 'FR'
  ? 'Redige un resume narratif hebdomadaire en francais clair. Structure le texte avec un court titre, les themes principaux, les livraisons, les corrections et les prochaines pistes si elles sont evidentes.'
  : 'Write a clear weekly narrative development summary in English. Structure it with a short title, main themes, shipped work, fixes, and next steps if they are evident.';

const data = {
  repository: config.repoFullName,
  weekStart: config.weekStart,
  weekEnd: config.weekEnd,
  commits,
  closedIssues,
  mergedPullRequests
};

return [{
  json: {
    config,
    data,
    claudeBody: {
      model: 'claude-sonnet-4-20250514',
      max_tokens: 1200,
      temperature: 0.3,
      system: 'You summarize GitHub development activity for engineering teams. Be accurate and do not invent work that is not present in the input data.',
      messages: [
        {
          role: 'user',
          content: `${instruction}\n\nRepository activity JSON:\n${JSON.stringify(data, null, 2)}`
        }
      ]
    }
  }
}];

const config = $('Build Claude Request').first().json.config;
const data = $('Build Claude Request').first().json.data;
const response = $json;
const summary = response.content?.map((part) => part.text || '').join('\n').trim()
  || 'No GitHub activity was recorded for this week.';

const stats = `${data.commits.length} commits · ${data.closedIssues.length} issues closed · ${data.mergedPullRequests.length} PRs merged`;

return [{
  json: {
    webhookUrl: config.discordWebhookUrl,
    body: {
      username: 'Weekly Dev Summary',
      content: `**${data.repository} weekly development summary**\n*${data.weekStart.slice(0, 10)} → ${data.weekEnd.slice(0, 10)}*\n${stats}\n\n${summary}`
    }
  }
}];
